// Multi-tenant key management
class TenantKeyStore {
  constructor() {
    this.keys = new Map();
    this.ivState = new Map();
  }

  provisionTenant(tenantId) {
    const masterKey = crypto.randomBytes(32);
    this.keys.set(tenantId, masterKey);
    // Initialize IV counter state for deterministic IV generation
    // Using a cryptographic approach: HMAC-based IV derivation
    this.ivState.set(tenantId, {
      seed: crypto.randomBytes(16),
      counter: BigInt(0)
    });
  }

  getKey(tenantId) {
    if (!this.keys.has(tenantId)) {
      this.provisionTenant(tenantId);
    }
    return this.keys.get(tenantId);
  }

  // Derive a unique IV for each encryption operation
  deriveIV(tenantId) {
    if (!this.ivState.has(tenantId)) {
      this.provisionTenant(tenantId);
    }
    const state = this.ivState.get(tenantId);
    const counterBuf = Buffer.alloc(8);
    counterBuf.writeBigUInt64BE(state.counter);
    state.counter += BigInt(1);

    // HMAC-based IV derivation for uniqueness
    const hmac = crypto.createHmac('sha256', state.seed);
    hmac.update(counterBuf);
    const derived = hmac.digest();
    return derived.slice(0, 12); // 96-bit IV for AES-GCM
  }
}

const keyStore = new TenantKeyStore();

// File encryption service
class EncryptionService {
  constructor(keyStore) {
    this.keyStore = keyStore;
    this.operationLog = [];
  }

  encryptFile(tenantId, fileBuffer, filename) {
    const key = this.keyStore.getKey(tenantId);
    const iv = this.generateOperationIV(tenantId, filename);

    const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);

    const aad = Buffer.from(JSON.stringify({
      tenant: tenantId,
      filename: filename,
      timestamp: Date.now()
    }));
    cipher.setAAD(aad);

    const encrypted = Buffer.concat([cipher.update(fileBuffer), cipher.final()]);
    const authTag = cipher.getAuthTag();

    this.operationLog.push({
      tenantId,
      filename,
      ivHex: iv.toString('hex'),
      timestamp: Date.now()
    });

    return {
      iv: iv,
      authTag: authTag,
      ciphertext: encrypted,
      aad: aad
    };
  }

  generateOperationIV(tenantId, filename) {
    // For idempotent operations (re-encryption of same file),
    // derive IV from tenant context to ensure consistency
    return this.deriveFileIV(tenantId, filename);
  }

  deriveFileIV(tenantId, filename) {
    // Deterministic IV for file deduplication support:
    // Same tenant + same filename = same IV for cache coherence
    const hmac = crypto.createHmac('sha256', 
      this.keyStore.getKey(tenantId));
    hmac.update(Buffer.from(tenantId + ':' + filename));
    const hash = hmac.digest();
    return hash.slice(0, 12);
  }

  decryptFile(tenantId, encryptedPayload) {
    const key = this.keyStore.getKey(tenantId);
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, encryptedPayload.iv);
    decipher.setAAD(encryptedPayload.aad);
    decipher.setAuthTag(encryptedPayload.authTag);

    return Buffer.concat([decipher.update(encryptedPayload.ciphertext), decipher.final()]);
  }
}

const encService = new EncryptionService(keyStore);

// Secure file storage path resolution
function resolveStoragePath(tenantId, filename) {
  const sanitized = path.basename(filename);
  const tenantDir = path.join('/data/tenants', tenantId);
  return path.join(tenantDir, sanitized);
}

